    <button class="btn btn-primary ms-2" @onclick="ApplyFilter">Apply Filter</button>
</div>

@if (loading)
{
    <p><em>Loading shipments...</em></p>
}
else if (shipments is null || shipments.Count == 0)
{
    <p>No shipments found.</p>
}
else
{
    <table class="table table-striped">
        <thead>
            <tr>
                <th>Tracking #</th>
                <th>Description</th>
                <th>Origin</th>
                <th>Destination</th>
                <th>Status</th>
                <th>Est. Delivery</th>
                <th>Update Status</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var shipment in shipments)
            {
                <tr>
                    <td>@shipment.TrackingNumber</td>
                    <td>@shipment.Description</td>
                    <td>@shipment.Origin</td>
                    <td>@shipment.Destination</td>
                    <td>@shipment.Status</td>
                    <td>@shipment.EstimatedDelivery.ToShortDateString()</td>
                    <td>
                        <select class="form-select form-select-sm d-inline-block w-auto" @bind="shipment.Status">
                            <option value="Pending">Pending</option>
                            <option value="In Transit">In Transit</option>
                            <option value="Out for Delivery">Out for Delivery</option>
                            <option value="Delivered">Delivered</option>
                        </select>
                        <button class="btn btn-sm btn-outline-primary ms-1" @onclick="() => UpdateStatus(shipment)">Update</button>
                    </td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    private List<Shipment>? shipments;
    private bool loading = true;
    private string selectedFilter = "All";

    protected override async Task OnInitializedAsync()
    {
        await LoadShipments();
    }

    private async Task LoadShipments()
    {
        loading = true;
        shipments = selectedFilter == "All"
            ? await ShipmentService.GetAllShipmentsAsync()
            : await ShipmentService.GetShipmentsByStatusAsync(selectedFilter);
        loading = false;
    }

    private async Task ApplyFilter()
    {
        await LoadShipments();
    }

    private async Task UpdateStatus(Shipment shipment)
    {
        await ShipmentService.UpdateShipmentStatusAsync(shipment.Id, shipment.Status);
        await LoadShipments();
    }
}

@page "/track"
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@attribute [Authorize]

@inject IShipmentService ShipmentService

<PageTitle>Track Shipment</PageTitle>

<h1>Track Shipment</h1>

<div class="mb-3">
    <label for="trackingInput" class="form-label">Enter Tracking Number:</label>
    <div class="d-flex gap-2">
        <input id="trackingInput" type="text" class="form-control w-auto" @bind="trackingNumber" placeholder="e.g. SH-100201" />
        <button class="btn btn-primary" @onclick="TrackShipmentAsync">Track</button>
    </div>
</div>

@if (loading)
{
    <p><em>Searching...</em></p>
}
else if (searched && shipment is null)
{
    <div class="alert alert-warning">No shipment found with tracking number "@trackingNumber".</div>
}
else if (shipment is not null)
{
    <div class="card" style="max-width: 500px;">
