// Add additional endpoints required by the Identity /Account Razor components.
app.MapAdditionalIdentityEndpoints();

// Shipment API endpoints
app.MapGet("/api/shipments", async (IShipmentService service) =>
    Results.Ok(await service.GetAllShipmentsAsync()))
    .RequireAuthorization();

app.MapGet("/api/shipments/status/{status}", async (string status, IShipmentService service) =>
    Results.Ok(await service.GetShipmentsByStatusAsync(status)))
    .RequireAuthorization();

app.MapGet("/api/shipments/track/{trackingNumber}", async (string trackingNumber, IShipmentService service) =>
{
    var shipment = await service.GetShipmentByTrackingNumberAsync(trackingNumber);
    return shipment is not null ? Results.Ok(shipment) : Results.NotFound();
}).RequireAuthorization();

app.MapPut("/api/shipments/{id}/status", async (int id, StatusUpdateRequest request, IShipmentService service) =>
{
    await service.UpdateShipmentStatusAsync(id, request.Status);
    return Results.NoContent();
}).RequireAuthorization();

app.Run();

public record StatusUpdateRequest(string Status);

