1. using System.Net.Http.Json;
2. using ShipmentTracker.Client.Models;
3. 
4. namespace ShipmentTracker.Client.Services;
5. 
6. public class ShipmentHttpService : IShipmentService
7. {
8.     private readonly HttpClient _http;
9. 
10.     public ShipmentHttpService(HttpClient http)
11.     {
12.         _http = http;
13.     }
14. 
15.     public async Task<List<Shipment>> GetAllShipmentsAsync()
16.     {
17.         return await _http.GetFromJsonAsync<List<Shipment>>("/api/shipments") ?? [];
18.     }
19. 
20.     public async Task<List<Shipment>> GetShipmentsByStatusAsync(string status)
21.     {
22.         return await _http.GetFromJsonAsync<List<Shipment>>($"/api/shipments/status/{Uri.EscapeDataString(status)}") ?? [];
23.     }
24. 
25.     public async Task<Shipment?> GetShipmentByTrackingNumberAsync(string trackingNumber)
26.     {
27.         var response = await _http.GetAsync($"/api/shipments/track/{Uri.EscapeDataString(trackingNumber)}");
28.         if (response.IsSuccessStatusCode)
29.         {
30.             return await response.Content.ReadFromJsonAsync<Shipment>();
31.         }
32.         return null;
33.     }
34. 
35.     public async Task UpdateShipmentStatusAsync(int id, string newStatus)
36.     {
37.         await _http.PutAsJsonAsync($"/api/shipments/{id}/status", new { status = newStatus });
38.     }
39. }
